sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
    //g_form.addInfoMessage('Client script is working');
    var ga = new GlideAjax('x_1403515_mfa_to_0.GOACallFlowFromClient');
    ga.addParam('sysparm_name', 'runFlowAction');

    ga.addParam('sysparm_submitter_id', g_form.getValue('submitter_id'));
    ga.addParam('sysparm_ticket', g_form.getValue('ticket_id'));
    ga.addParam('sysparm_user_email', g_form.getValue('u_user_email'));
    ga.addParam('sysparm_option', newValue);

    ga.getXMLAnswer(function(response) {

        if (!response) return;

        var result = JSON.parse(response);

        g_form.setValue('mfa_execution_details', result.message);

        if (result.status !== 'success') {
            g_form.showFieldMsg(
                'mfa_execution_details',
                'Action completed with warnings',
                'warning'
            );
        }
    });
}
